odoo.template:
[class^="pictogram-"],
[class*=" pictogram-"] {
    display: inline-block;

    width: 1.2em;
    height: 1.2em;

    background-color: currentColor;

    vertical-align: middle;

    mask-size: contain;
    mask-repeat: no-repeat;
    mask-position: center;
}


. {
    mask-image: url("/web/image/theme.compassion.pictograms//svg_file");
}
